receiver=dict(available=True,reason='NO_FRONT',front_id='',nearest_internal=None,leader=None)
if front:
    receiver['front_id']=front.vehicle_id
    route=tuple(conn.vehicle.getRoute(front.vehicle_id));idx=conn.vehicle.getRouteIndex(front.vehicle_id)
    if route[idx:idx+3]!=('ramp_storage','ramp_accel','merge_section'):raise ValueError('checked receiver route changed')
    nearest=min(internal,key=lambda k:internal[k]['position_m']-internal[k]['length_m']) if internal else None
    clearance=internal[nearest]['position_m']-internal[nearest]['length_m'] if nearest else None
    receiver.update(nearest_internal=nearest,nearest_internal_rear_clearance_m=clearance,required_front_clearance_m=front.length_m+front.min_gap_m)
    if nearest and clearance<front.length_m+front.min_gap_m:receiver.update(available=False,reason='INTERNAL_RECEIVER_CLEARANCE')
    raw=conn.vehicle.getLeader(front.vehicle_id,478.67)
    if raw:
        leader_id,gap=raw;typ=conn.vehicle.getTypeID(leader_id);lane=conn.vehicle.getLaneID(leader_id)
        if lane not in (INTERNAL,'ramp_accel_0',':freeway_merge_2_0','merge_section_0','merge_section_1','merge_section_2'):raise ValueError('leader off checked receiving path')
        lead=LeaderState(leader_id,lane,gap,conn.vehicle.getSpeed(leader_id),conn.vehicletype.getEmergencyDecel(typ))
        state=VehicleState(front.position_m,front.speed_m_s,front.length_m,front.min_gap_m,front.accel_m_s2,front.normal_decel_m_s2)
        secure=conn.vehicle.getSecureGap(**secure_gap_query(front.vehicle_id,state,lead))
        if not math.isfinite(secure) or secure<0:raise ValueError('unknown secure receiving gap')
        receiver['leader']=dict(vehicle_id=leader_id,lane_id=lane,gap_excluding_minGap_m=gap,secure_gap_m=secure)
        if gap+1e-9<secure+1.1:receiver.update(available=False,reason='LEADER_SECURE_GAP')
    if receiver['available']:receiver['reason']='AVAILABLE'
return vehicles,ids,internal,receiver

if conn.trafficlight.getProgram(TLS) != p['program']: errors.append('PROGRAM_MISMATCH')
if conn.trafficlight.getControlledLinks(TLS) != ((('ramp_storage_0','ramp_accel_0',INTERNAL),),): errors.append('POST_LINK_MISMATCH')
try:
    _, _, post_internal, post_receiver = self.observe(conn)
    if type(post_receiver.get('available')) is not bool: errors.append('UNKNOWN_POST_RECEIVER')
    if post_receiver.get('available') is False and p['motion'] == 'G': errors.append('POST_GREEN_RECEIVER_DENIED')
    if set(post_internal) != set(conn.lane.getLastStepVehicleIDs(INTERNAL)): errors.append('POST_INTERNAL_COVERAGE_MISMATCH')
    row['post_receiver'] = post_receiver
except Exception as exc:
    errors.append('POST_OBSERVATION_UNKNOWN:'+type(exc).__name__)
counters = {'colliding_vehicles': conn.simulation.getCollidingVehiclesNumber(),
    'starting_teleports': conn.simulation.getStartingTeleportNumber(), 'ending_teleports': conn.simulation.getEndingTeleportNumber()}
row['native_event_counters'] = counters
if any(counters.values()): errors.append('COLLISION_OR_TELEPORT')
if p['motion'] == 'r' and recs: errors.append('RED_CROSSING')
braking = {'speed_difference_ids': sorted(before & after), 'after_acceleration_ids': sorted(after),
    'excluded_before_only_ids': sorted(before-after), 'arrived_ids': sorted(arrived),
    'speed_difference_m_s2': {}, 'actual_acceleration_m_s2': {},
    'coverage': 'BEFORE_INTERSECTION_AFTER_DIFFERENCE_AND_AFTER_POPULATION_GETTER_NOT_GLOBAL'}
row['braking_observation'] = braking
for vid in sorted(before & after):
    difference = world[vid]['speed_m_s']-p['world'][vid]['speed_m_s']
    braking['speed_difference_m_s2'][vid] = difference
    if difference < -4.5-1e-6: errors.append('ORDINARY_BRAKING_EXCEEDED:'+vid)
for vid in sorted(after):
    a = conn.vehicle.getAcceleration(vid)
    braking['actual_acceleration_m_s2'][vid] = a if math.isfinite(a) else None
    if not math.isfinite(a) or a < -4.5-1e-6: errors.append('UNKNOWN_OR_EXCESSIVE_ACCELERATION:'+vid)
if any(s in native_warning_text.lower() for s in ('emergency braking','emergency stop','collision','teleport')): errors.append('NATIVE_WARNING')
if errors:
    self.paused = True
    row.update(status='STOP_OBSERVED_AFTER_STEP', reasons=errors)
    raise DiagnosticStop(';'.join(errors))
if p['time_s'] == 1206:
    self.checkpoint_pending = True
    row['status'] = 'MANDATORY_FIRST_RED_CHECKPOINT_PENDING'
if self.last_end >= 1272:
    require(self.checkpoint_verified, 'FIRST_RED_CHECKPOINT_MISSING')
    require(len(self.ledger.rows) == 3 and all(c['completed'] for c in self.ledger.rows), 'THREE_CYCLES_INCOMPLETE')
    self.paused = True
    row['status'] = 'THREE_CYCLES_COMPLETED_MANDATORY_STOP_NOT_QUALIFIED'
return row
